heckpoint_json ->> 'mappedModelSpecEtag') ~ '^[0-9a-f]{64}$' AND project_key IS NOT NULL AND pg_catalog.btrim(project_key) <> '' AND accepted_external_checksum ~ '^[0-9a-f]{64}$' AND accepted_implementation_revision > 0 AND accepted_implementation_checksum ~ '^[0-9a-f]{64}$' AND mapped_model_spec_revision > 0 AND mapped_model_spec_etag ~ '^[0-9a-f]{64}$' AND status IN ('CREATED', 'UPDATED', 'SKIPPED') ) ) ) IS TRUE), ADD CONSTRAINT ck_model_spec_import_result_pre_pins_complete CHECK (( pre_attempt_pins_json IS NULL OR ( pg_catalog.jsonb_typeof(pre_attempt_pins_json) = 'object' AND pg_catalog.jsonb_exists_all(pre_attempt_pins_json, ARRAY[ 'modelRevision', 'modelChecksum', 'implementationRevision', 'implementationChecksum' ]) AND pg_catalog.jsonb_typeof( pre_attempt_pins_json -> 'modelRevision' ) = 'number' AND (pre_attempt_pins_json ->> 'modelRevision') ~ '^[1-9][0-9]*$' AND pg_catalog.jsonb_typeof( pre_attempt_pins_json -> 'modelChecksum' ) = 'string' AND (pre_attempt_pins_json ->> 'modelChecksum') ~ '^[0-9a-f]{64}$' AND pg_catalog.jsonb_typeof( pre_attempt_pins_json -> 'implementationRevision' ) = 'number' AND (pre_attempt_pins_json ->> 'implementationRevision') ~ '^[1-9][0-9]*$' AND pg_catalog.jsonb_typeof( pre_attempt_pins_json -> 'implementationChecksum' ) = 'string' AND (pre_attempt_pins_json ->> 'implementationChecksum') ~ '^[0-9a-f]{64}$' ) ) IS TRUE) $result_ddl$, target_schema ); END $migration$;

